-- TEST ONLY: reduced schema in a newly created owned disposable database.
-- Not a Goblin production migration or a full Work persistence model.
REVOKE CREATE ON SCHEMA public FROM PUBLIC;
GRANT USAGE ON SCHEMA public TO goblin_app;

CREATE TABLE public.work_item (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    objective text NOT NULL,
    state jsonb NOT NULL,
    version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
    status text NOT NULL DEFAULT 'Ready',
    updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE public.connector_work_read_grant (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    issuer text COLLATE "C" NOT NULL CHECK (octet_length(issuer) BETWEEN 1 AND 512),
    subject text COLLATE "C" NOT NULL CHECK (octet_length(subject) BETWEEN 1 AND 256),
    resource text COLLATE "C" NOT NULL CHECK (octet_length(resource) BETWEEN 1 AND 512),
    work_id bigint NOT NULL REFERENCES public.work_item(id) ON DELETE CASCADE,
    approved_at timestamptz NOT NULL,
    expires_at timestamptz NOT NULL CHECK (expires_at > approved_at),
    revoked_at timestamptz CHECK (revoked_at >= approved_at),
    UNIQUE (issuer, subject, resource, work_id)
);

-- Source can read only the projection and grant predicates, not history or
-- objective, and cannot approve, revoke or mutate Work as goblin_app.
REVOKE ALL ON public.work_item, public.connector_work_read_grant FROM PUBLIC, goblin_app;
GRANT SELECT (id, version, status, updated_at) ON public.work_item TO goblin_app;
GRANT SELECT (issuer, subject, resource, work_id, approved_at, expires_at, revoked_at)
    ON public.connector_work_read_grant TO goblin_app;
